import json
from pathlib import Path
for p in [
  Path('/Users/mac/Desktop/CHcode/omdb/config.json'),
  Path('/Users/mac/Desktop/CHcode/.claude/database/dc-platform.json'),
  Path.home()/'.dc-platform/config.json',
]:
  if not p.exists():
    print(f'missing {p}')
    continue
  d=json.loads(p.read_text())
  print('===', p)
  def walk(obj, prefix=''):
    if isinstance(obj, dict):
      for k,v in obj.items():
        lk=k.lower()
        if any(x in lk for x in ('mysql','metadata','token','password','url')):
          if isinstance(v,str) and ('mysql' in v.lower() or '@' in v or 'pass' in lk):
            # redact
            if 'mysql' in v.lower():
              import re
              print(f'{prefix}{k}=', re.sub(r'://([^:]+):([^@]+)@', r'://\1:***@', v)[:120])
            else:
              print(f'{prefix}{k}=', '<set len=%d>'%len(v))
          else:
            print(f'{prefix}{k}=', type(v).__name__, (str(v)[:80] if not isinstance(v,dict) else '{...}'))
        else:
          walk(v, prefix+k+'.')
    elif isinstance(obj, list):
      for i,v in enumerate(obj[:3]):
        walk(v, prefix+f'[{i}].')
  walk(d)
